revoke all on public.admin_queue_versions,public.admin_work_items,public.admin_work_item_events,public.admin_operational_action_requests,public.admin_operational_action_decisions,public.admin_support_access_grants from public,anon,authenticated,service_role;grant select on public.admin_queue_versions,public.admin_work_items,public.admin_work_item_events,public.admin_operational_action_requests,public.admin_operational_action_decisions,public.admin_support_access_grants to authenticated;
create policy admin_queue_scoped_read on public.admin_queue_versions for select to authenticated using(private.has_platform_role(required_role_codes)or private.has_platform_role(array['READ_ONLY_AUDITOR']));create policy admin_work_scoped_read on public.admin_work_items for select to authenticated using(private.admin_has_queue_access(queue_version_id));create policy admin_work_events_scoped_read on public.admin_work_item_events for select to authenticated using(exists(select 1 from public.admin_work_items w where w.id=work_item_id and private.admin_has_queue_access(w.queue_version_id)));create policy admin_actions_scoped_read on public.admin_operational_action_requests for select to authenticated using(private.admin_command_access()or private.has_platform_role(array['READ_ONLY_AUDITOR']));create policy admin_action_decisions_scoped_read on public.admin_operational_action_decisions for select to authenticated using(exists(select 1 from public.admin_operational_action_requests x where x.id=action_request_id and(private.admin_command_access()or private.has_platform_role(array['READ_ONLY_AUDITOR']))));create policy admin_support_grants_scoped_read on public.admin_support_access_grants for select to authenticated using(support_user_id=auth.uid()or private.admin_command_access()or private.has_platform_role(array['READ_ONLY_AUDITOR']));
revoke all on function private.admin_has_queue_access(uuid,uuid),private.admin_command_access(uuid),private.begin_admin_command(text,text,text,uuid),private.finish_admin_command(text,text,uuid,jsonb)from public,anon,authenticated,service_role;grant execute on function private.admin_has_queue_access(uuid,uuid),private.admin_command_access(uuid)to authenticated;
