grant execute on function public.open_admin_work_item(text,uuid,text,text,text,text,text,text,timestamptz,jsonb,text,text,uuid),public.claim_admin_work_item(uuid,integer,text,text,uuid),public.resolve_admin_work_item(uuid,text,text,jsonb,integer,text,uuid),public.request_admin_operational_action(uuid,uuid,text,text,text,text,text,jsonb,text,text,uuid,text,timestamptz,text,uuid),public.decide_admin_operational_action(uuid,text,text,integer,text,uuid)to authenticated;grant execute on function public.complete_admin_operational_action(uuid,text,boolean,uuid)to service_role;
